package by.bsuir.identity;

import by.bsuir.repair.contract.*; import by.bsuir.repair.runtime.*; import io.grpc.Status; import io.grpc.stub.StreamObserver;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner;
import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;

@Service
public class IdentityGrpcService extends IdentityServiceGrpc.IdentityServiceImplBase implements ApplicationRunner {
 private final JdbcTemplate jdbc; private final StringRedisTemplate redis; private final PasswordEncoder encoder; private final Jsons jsons; private final OutboxService outbox; private final SecretKey key; private final String issuer; private final Duration lifetime;
 public IdentityGrpcService(JdbcTemplate jdbc,StringRedisTemplate redis,PasswordEncoder encoder,Jsons jsons,OutboxService outbox,@Value("${security.jwt.secret}")String secret,@Value("${security.jwt.issuer:repair-auth-service}")String issuer,@Value("${security.jwt.lifetime:PT2H}")Duration lifetime){this.jdbc=jdbc;this.redis=redis;this.encoder=encoder;this.jsons=jsons;this.outbox=outbox;this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.issuer=issuer;this.lifetime=lifetime;}
 @Override public void run(ApplicationArguments args){seed("client@example.com","Client123!","CLIENT","Тестовый клиент");seed("employee@example.com","Employee123!","EMPLOYEE","Тестовый сотрудник");seed("admin@example.com","Admin123!","ADMIN","Администратор");}
 private void seed(String email,String password,String role,String name){if(jdbc.queryForObject("select count(*) from users where email=?",Integer.class,email)==0){UUID id=UUID.randomUUID();UUID roleId=jdbc.queryForObject("select id from roles where name=?",UUID.class,role);jdbc.update("insert into users(id,role_id,email,password_hash,enabled,created_at) values(?,?,?,?,true,?)",id,roleId,email,encoder.encode(password),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));if(role.equals("CLIENT"))jdbc.update("insert into clients(id,user_id,full_name,phone) values(?,?,?,?)",UUID.randomUUID(),id,name,"+375290000000");if(role.equals("EMPLOYEE"))jdbc.update("insert into employees(id,user_id,full_name,position) values(?,?,?,?)",UUID.randomUUID(),id,name,"Мастер");}}
 @Override @Transactional public void register(JsonMessage request,StreamObserver<JsonMessage> observer){try{jsons.reply(observer,register(jsons.read(request)));}catch(Throwable e){jsons.fail(observer,e);}}
 public Map<String,Object> register(Map<String,Object> in){String email=jsons.string(in,"email").trim().toLowerCase();String password=jsons.string(in,"password");if(password.length()<8)throw new IllegalArgumentException("password must contain at least 8 characters");if(jdbc.queryForObject("select count(*) from users where lower(email)=lower(?)",Integer.class,email)>0)throw Status.ALREADY_EXISTS.withDescription("User already exists").asRuntimeException();UUID userId=UUID.randomUUID();UUID roleId=jdbc.queryForObject("select id from roles where name='CLIENT'",UUID.class);jdbc.update("insert into users(id,role_id,email,password_hash,enabled,created_at) values(?,?,?,?,true,?)",userId,roleId,email,encoder.encode(password),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));jdbc.update("insert into clients(id,user_id,full_name,phone) values(?,?,?,?)",UUID.randomUUID(),userId,Objects.toString(in.getOrDefault("fullName","Клиент")),Objects.toString(in.getOrDefault("phone","")));outbox.enqueue(EventTopics.USER,"UserRegistered",userId,Map.of("userId",userId,"email",email,"role","CLIENT"));return user(userId);}
 @Override public void login(JsonMessage request,StreamObserver<JsonMessage> observer){try{jsons.reply(observer,login(jsons.read(request)));}catch(Throwable e){jsons.fail(observer,e);}}
 public Map<String,Object> login(Map<String,Object> in){String email=jsons.string(in,"email").trim().toLowerCase();var rows=jdbc.queryForList("select u.id,u.email,u.password_hash,u.enabled,r.name role from users u join roles r on r.id=u.role_id where lower(u.email)=lower(?)",email);if(rows.isEmpty()||!Boolean.TRUE.equals(rows.get(0).get("enabled"))||!encoder.matches(jsons.string(in,"password"),rows.get(0).get("password_hash").toString()))throw Status.UNAUTHENTICATED.withDescription("Invalid email or password").asRuntimeException();var row=rows.get(0);UUID id=(UUID)row.get("id");String sid=UUID.randomUUID().toString();Instant now=Instant.now(),expires=now.plus(lifetime);String token=Jwts.builder().issuer(issuer).subject(id.toString()).claim("email",email).claim("role",row.get("role").toString()).claim("sid",sid).issuedAt(Date.from(now)).expiration(Date.from(expires)).signWith(key).compact();redis.opsForValue().set("auth:session:"+sid,jsons.writeString(Map.of("userId",id,"email",email,"role",row.get("role"))),lifetime);return Map.of("accessToken",token,"tokenType","Bearer","sessionId",sid,"expiresAt",expires.toString(),"user",user(id));}
 @Override public void logout(SessionRequest request,StreamObserver<Empty> observer){redis.delete("auth:session:"+request.getSessionId());observer.onNext(Empty.getDefaultInstance());observer.onCompleted();}
 @Override public void validateSession(SessionRequest request,StreamObserver<AccessResponse> observer){try{String value=redis.opsForValue().get("auth:session:"+request.getSessionId());if(value==null){observer.onNext(AccessResponse.newBuilder().setActive(false).build());observer.onCompleted();return;}var map=jsons.read(value);observer.onNext(AccessResponse.newBuilder().setActive(true).setUserId(map.get("userId").toString()).setEmail(map.get("email").toString()).setRole(map.get("role").toString()).build());observer.onCompleted();}catch(Throwable e){observer.onError(Status.UNAVAILABLE.withDescription("Session store unavailable").withCause(e).asRuntimeException());}}
 @Override public void getUserAccess(JsonMessage request,StreamObserver<JsonMessage> observer){try{jsons.reply(observer,user(UUID.fromString(jsons.string(jsons.read(request),"id"))));}catch(Throwable e){jsons.fail(observer,e);}}
 @Override public void listUsers(JsonMessage request,StreamObserver<JsonMessage> observer){try{var rows=jdbc.queryForList("select u.id,u.email,u.enabled,u.created_at AS \"createdAt\",r.name AS role from users u join roles r on r.id=u.role_id order by u.created_at");jsons.reply(observer,rows);}catch(Throwable e){jsons.fail(observer,e);}}
 @Override @Transactional public void changeRole(JsonMessage request,StreamObserver<JsonMessage> observer){try{var in=jsons.read(request);UUID id=UUID.fromString(jsons.string(in,"userId"));String role=jsons.string(in,"role");UUID roleId=jdbc.queryForObject("select id from roles where name=?",UUID.class,role);if(jdbc.update("update users set role_id=? where id=?",roleId,id)==0)throw Status.NOT_FOUND.withDescription("User not found").asRuntimeException();jsons.reply(observer,user(id));}catch(Throwable e){jsons.fail(observer,e);}}
 @Override @Transactional public void setEnabled(JsonMessage request,StreamObserver<JsonMessage> observer){try{var in=jsons.read(request);UUID id=UUID.fromString(jsons.string(in,"userId"));if(jdbc.update("update users set enabled=? where id=?",jsons.bool(in,"enabled",true),id)==0)throw Status.NOT_FOUND.withDescription("User not found").asRuntimeException();jsons.reply(observer,user(id));}catch(Throwable e){jsons.fail(observer,e);}}
 private Map<String,Object> user(UUID id){var rows=jdbc.queryForList("select u.id,u.email,u.enabled,u.created_at AS \"createdAt\",r.name AS role from users u join roles r on r.id=u.role_id where u.id=?",id);if(rows.isEmpty())throw Status.NOT_FOUND.withDescription("User not found").asRuntimeException();return rows.get(0);}
}


